The Nearest Neighbour Index (NNI) compares mean nearest-neighbour distances in observed data to expected distances under complete spatial randomness (CSR). $$\text{NNI} = \frac{\text{Observed Mean Distance}}{\text{Expected Mean Distance}}$$ NNI ≈ 1 : Pattern consistent with CSR (random) NNI < 1 : Clustering (points closer than random expectation) NNI > 1 : Dispersion (points farther apart than random) # Calculate nearest neighbour index for point pattern
result <- wbw_nearest_neighbour_index( input = 'earthquake_epicenters.gpkg', session = s
) # Extract statistics
cat('NNI:', result$nni_value, '\n')
cat('z-score:', result$z_score, '\n')
cat('p-value:', result$p_value, '\n') Workflow: Analyzing Wildfire Clustering s <- wbw_session()
wbw_set_working_directory('/data/wildfire', session = s) # Load fire event points
fires <- wbw_read_vector('wildfire_points.gpkg', session = s) # Test if fires cluster or disperse
nni_result <- wbw_nearest_neighbour_index( input = 'wildfire_points.gpkg', session = s
) # If NNI significantly < 1, fires cluster → investigate common conditions
if (nni_result$p_value < 0.05 && nni_result$nni_value < 1) { cat('Fire clustering detected (p =', nni_result$p_value, ')\n') cat('Investigate drought, fuel loads, and ignition source patterns\n')
} else if (nni_result$nni_value > 1) { cat('Fire dispersion detected: likely independent ignition sources\n')
}

